const checks = {
  'reconcile-phase': ['src/agent/phases/reconcile.ts'],
  'implement-phase': ['src/agent/phases/implement.ts'],
  'mcp-servers': ['src/agent/mcp/mcp-config.ts'],
  'instructions-and-skills': ['src/agent/instructions/instruction-files.ts', 'src/agent/skills/skill-index.ts'],
  'docs-map': ['src/agent/docs-map/build.ts', 'src/agent/phases/docs-map.ts'],
  'docs-evaluation': ['src/agent/phases/docs-evaluation.ts'],
}
const out = []
for (const [feat, files] of Object.entries(checks)) {
  const sizes = []
  for (const f of files) {
    try { sizes.push(`${f}=${(await read(f)).length}b`) } catch (e) { sizes.push(`${f}=MISSING`) }
  }
  out.push(`${feat}: ${sizes.join(', ')}`)
}
// markers the feature docs name explicitly
const markers = [
  'Evaluate docs', 'buildDocsMap', 'buildRepoMap', 'reconnectMcp', 'planIgnore',
  'contextWindows', 'retrievalProfile', 'ado', 'retrieve(', 'claim',
]
const hits = []
for (const m of markers) {
  const r = await grep({ pattern: m.replace(/[(]/g, '\\('), output_mode: 'files_with_matches' })
  const n = r.split('\n').filter(l => l.trim() && !l.startsWith('Found') && !l.startsWith('No ')).length
  hits.push(`${m} -> ${n} files`)
}
return out.join('\n') + '\n--- markers ---\n' + hits.join('\n')

const pats = ['contextWindows', 'retrievalProfile', 'kiwiAgent.ado', 'Evaluate docs', 'totalCost|sessionCost|session total']
const out = []
for (const p of pats) {
  for (const dir of ['src', 'package.json']) {
    const r = await grep({ pattern: p, path: dir, output_mode: 'content' })
    const lines = r.split('\n').filter(l => l.trim()).slice(0, 6)
    out.push(`[${p}] in ${dir}: ${lines.length ? '\n  ' + lines.join('\n  ') : 'none'}`)
  }
}
return out.join('\n')

const built = ['reconcile-phase', 'implement-phase', 'mcp-servers', 'instructions-and-skills', 'docs-map', 'docs-evaluation']
const left = ['session-cost', 'composer-input', 'retrieval-subsession', 'coordination', 'ado-integration', 'own-loop-compaction']

const header = (await read('docs/features/README.md')).split('\n').slice(0, 4).join('\n')
await write('docs/features/README.md', header + left.map((f, i) => `${i + 1}. [${f}.md](${f}.md)`).join('\n') + '\n')

const paths = built.map(f => `docs/features/${f}.md`)
await bash({ command: `rm ${paths.join(' ')}`, description: 'Delete feature docs whose feature is already built' })

const remaining = (await glob({ pattern: 'docs/features/*.md' })).split('\n').filter(Boolean)
return `deleted ${built.length}\nremaining on disk:\n${remaining.join('\n')}\n--- README diff ---\n${await preview()}`
